<?php namespace App\Http\Controllers; use App\Models\{Address,Discount,Order,OrderItem,PaymentTransaction,Product,ProductVariant,RewardTransaction,ShippingMethod}; use App\Services\CartService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class CheckoutController extends Controller { public function show(CartService $c){if(!$c->count()) return redirect('/cart'); return view('site.checkout',['items'=>$c->items(),'subtotal'=>$c->subtotal(),'addresses'=>auth()->user()->addresses,'shippingMethods'=>ShippingMethod::where('is_active',true)->get()]);} public function store(Request $r,CartService $c){$d=$r->validate(['name'=>'required|max:120','email'=>'required|email','phone'=>'nullable|max:40','line1'=>'required|max:180','line2'=>'nullable|max:180','city'=>'required|max:120','county'=>'nullable|max:120','postcode'=>'nullable|max:30','country'=>'required|size:2','shipping_method'=>'nullable|max:80','payment_method'=>'required|in:cod,bank_transfer,manual','notes'=>'nullable|max:2000','discount_code'=>'nullable|max:60']);abort_if(!$c->count(),422,'Cart is empty');$subtotal=$c->subtotal();$shipping=0;$method=null;if($d['shipping_method']){$method=ShippingMethod::where('code',$d['shipping_method'])->where('is_active',true)->first();if($method)$shipping=($method->free_over&&$subtotal>=$method->free_over)?0:(float)$method->price;}$discount=0;$discountCode=null;if($d['discount_code']){$coupon=Discount::where('code',strtoupper($d['discount_code']))->where('is_active',true)->first();if($coupon&&$subtotal>=$coupon->minimum_order){$discount=$coupon->type==='percent'?$subtotal*((float)$coupon->value/100):min($subtotal,(float)$coupon->value);$discountCode=$coupon->code;}}$order=DB::transaction(function()use($d,$c,$subtotal,$shipping,$discount,$discountCode,$method){$o=Order::create(['user_id'=>auth()->id(),'number'=>'ER-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'status'=>'processing','payment_status'=>$d['payment_method']==='cod'?'pay_on_delivery':'pending','subtotal'=>$subtotal,'shipping'=>$shipping,'discount'=>$discount,'total'=>max(0,$subtotal+$shipping-$discount),'currency'=>'EUR','email'=>$d['email'],'phone'=>$d['phone']??null,'shipping_method'=>$method?->name,'payment_method'=>$d['payment_method'],'discount_code'=>$discountCode,'notes'=>$d['notes']??null,'shipping_address'=>['name'=>$d['name'],'line1'=>$d['line1'],'line2'=>$d['line2']??null,'city'=>$d['city'],'county'=>$d['county']??null,'postcode'=>$d['postcode']??null,'country'=>$d['country']]]);foreach($c->items() as $i){$p=Product::find($i['product_id']);$v=$i['variant_id']?ProductVariant::find($i['variant_id']):null;OrderItem::create(['order_id'=>$o->id,'product_id'=>$p?->id,'product_variant_id'=>$v?->id,'name'=>$i['name'],'sku'=>$i['sku'],'quantity'=>$i['quantity'],'unit_price'=>$i['price'],'total'=>$i['price']*$i['quantity'],'options'=>$i['options']]);if($v){$v->decrement('stock',min($v->stock,$i['quantity']));}elseif($p){$p->decrement('stock',min($p->stock,$i['quantity']));}}PaymentTransaction::create(['order_id'=>$o->id,'provider'=>$d['payment_method'],'amount'=>$o->total,'currency'=>'EUR','status'=>$d['payment_method']==='cod'?'pending':'awaiting_payment']);RewardTransaction::create(['user_id'=>auth()->id(),'points'=>(int)floor($o->total),'type'=>'earn','reference'=>$o->number,'description'=>'Points earned from order']);$c->clear();return $o;});return redirect()->route('order.success',$order)->with('success','Order placed successfully.');} public function success(Order $order){abort_unless($order->user_id===auth()->id(),403);return view('site.order-success',compact('order'));}}
